sys_script.script:
(function executeRule(current, previous) {
    var calc = new x_2298436_snackf_0.SnackFlowCalc()

    // DELTA ONLY. 'dispatched_quantity' is a running total on the sales order line,
    // so posting nowQty would re-post everything already dispatched and double-count
    // the item on every subsequent edit of the line. Only the increment since the
    // previous save may be posted to the stock ledger.
    var nowQty = calc.toNum(current.getValue('dispatched_quantity'))
    // On insert there is no 'previous' record, so the baseline is 0.
    var prevQty = previous ? calc.toNum(previous.getValue('dispatched_quantity')) : 0
    var delta = calc.round2(nowQty - prevQty)

    if (delta <= 0) {
        // Nothing newly dispatched. A negative delta is a downward correction, and
        // this rule deliberately posts nothing for it: reversing stock that already
        // left the warehouse is a human decision (a 'return' or 'stock_adjustment'
        // transaction entered on purpose), not something this rule should guess at.
        return
    }

    var productId = current.getValue('product')
    if (!productId) {
        // Finished-product movements are keyed on 'product'. Without it there is no
        // item to move, so there is nothing to post.
        return
    }

    // Resolve the parent sales order number for the legacy text field. Guarded, so a
    // missing/deleted parent leaves reference_number empty instead of 'undefined'.
    var salesOrderId = current.getValue('sales_order')
    var salesOrderNumber = ''
    if (salesOrderId) {
        var salesOrder = new GlideRecord('x_2298436_snackf_0_sales_order')
        if (salesOrder.get(salesOrderId)) {
            salesOrderNumber = salesOrder.getValue('number') || ''
        }
    }

    // ONE dispatch row for exactly the delta.
    var txn = new GlideRecord('x_2298436_snackf_0_stock_transaction')
    txn.initialize()
    txn.setValue('item_type', 'finished_product')
    txn.setValue('product', productId)
    txn.setValue('transaction_type', 'dispatch')
    txn.setValue('quantity', delta)
    // getValue() yields the internal UTC format setValue() expects. getDisplayValue() would
    // write a timezone-dependent display string into a datetime column.
    txn.setValue('transaction_date', new GlideDateTime().getValue())
    txn.setValue('sales_order', salesOrderId) // true reference field
    txn.setValue('reference_number', salesOrderNumber) // legacy text field kept consistent
    txn.setValue(
        'remarks',
        'Auto-posted by SnackFlow Dispatch Stock Posting for ' + current.getValue('number') + ' (delta ' + delta + ').'
    )

    var inserted = txn.insert()
    if (!inserted) {
        // 'SnackFlow Stock Negative Check' (before insert, order 150) legitimately
        // aborts this insert when there is not enough finished stock on hand. Report
        // it loudly instead of swallowing it, and never try to force the row through.
        gs.error(
            'SnackFlow Dispatch Stock Posting: stock transaction insert was rejected for sales order detail ' +
                current.getValue('number') +
                ' (' +
                current.getUniqueValue() +
                '), product ' +
                productId +
                ', delta ' +
                delta +
                '. Finished-product stock is most likely insufficient - review the stock balance and post a manual adjustment if required.'
        )
    }
})(current, previous)
